import { useState } from "react";
import { Link, useNavigate, useSearchParams } from "react-router-dom";
import {
    ArrowLeft,
    LockKeyhole,
    Eye,
    EyeOff,
    Loader2,
    CheckCircle2,
} from "lucide-react";
import axios from "axios";

export default function ResetPassword() {
    const navigate = useNavigate();
    const [searchParams] = useSearchParams();

    // Token should be generated by your backend.
    const token = searchParams.get("token");

    const [password, setPassword] = useState("");
    const [confirmPassword, setConfirmPassword] = useState("");
    const [showPassword, setShowPassword] = useState(false);
    const [showConfirmPassword, setShowConfirmPassword] = useState(false);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState("");
    const [success, setSuccess] = useState(false);

    const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        setError("");

        if (!token) {
            setError("Invalid or missing reset token. Please request a new reset link.");
            return;
        }

        if (password.length < 8) {
            setError("Password must be at least 8 characters long.");
            return;
        }

        if (password !== confirmPassword) {
            setError("Passwords do not match.");
            return;
        }

        setLoading(true);

        try {
            await axios.post("/api/auth/reset-password", {
                token,
                password,
            });

            setSuccess(true);
        } catch (err: unknown) {
            if (axios.isAxiosError(err)) {
                setError(
                    err.response?.data?.message ||
                    "Unable to reset password. Please try again."
                );
            } else {
                setError("Something went wrong. Please try again.");
            }
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="flex min-h-screen items-center justify-center bg-gradient-to-br from-indigo-50 via-white to-purple-50 p-4">
            <div className="w-full max-w-xl rounded-3xl border border-gray-100 bg-white p-7 shadow-xl sm:p-10">
                <Link
                    to="/login"
                    className="mb-8 inline-flex items-center gap-2 text-sm font-semibold text-gray-500 transition hover:text-indigo-600"
                >
                    <ArrowLeft size={18} />
                    Back to login
                </Link>

                <div className="mb-6 flex h-16 w-16 items-center justify-center rounded-2xl bg-indigo-100 text-indigo-600">
                    {success ? (
                        <CheckCircle2 size={32} />
                    ) : (
                        <LockKeyhole size={32} />
                    )}
                </div>

                {success ? (
                    <>
                        <h1 className="text-3xl font-extrabold tracking-tight text-gray-900">
                            Password reset!
                        </h1>

                        <p className="mt-3 text-sm leading-6 text-gray-500">
                            Your password has been changed successfully. You can now sign
                            in with your new password.
                        </p>

                        <button
                            onClick={() => navigate("/login")}
                            className="mt-8 w-full rounded-xl bg-indigo-600 px-4 py-3 font-bold text-white transition hover:bg-indigo-700"
                        >
                            Go to login
                        </button>
                    </>
                ) : (
                    <>
                        <h1 className="text-3xl font-extrabold tracking-tight text-gray-900">
                            Reset password
                        </h1>

                        <p className="mt-3 text-sm leading-6 text-gray-500">
                            Create a new password for your account. Use at least 8
                            characters to keep your account secure.
                        </p>

                        <form onSubmit={handleSubmit} className="mt-8 space-y-5">
                            <div>
                                <label
                                    htmlFor="password"
                                    className="mb-2 block text-sm font-semibold text-gray-700"
                                >
                                    New password
                                </label>

                                <div className="flex items-center rounded-xl border border-gray-200 bg-gray-50 pr-3 transition focus-within:border-indigo-500 focus-within:ring-4 focus-within:ring-indigo-100">
                                    <input
                                        id="password"
                                        type={showPassword ? "text" : "password"}
                                        autoComplete="new-password"
                                        placeholder="Enter new password"
                                        value={password}
                                        onChange={(e) => setPassword(e.target.value)}
                                        className="w-full bg-transparent px-4 py-3 outline-none"
                                        required
                                        minLength={8}
                                    />

                                    <button
                                        type="button"
                                        onClick={() => setShowPassword(!showPassword)}
                                        aria-label={showPassword ? "Hide password" : "Show password"}
                                        className="text-gray-500 hover:text-indigo-600"
                                    >
                                        {showPassword ? <EyeOff size={19} /> : <Eye size={19} />}
                                    </button>
                                </div>
                            </div>

                            <div>
                                <label
                                    htmlFor="confirmPassword"
                                    className="mb-2 block text-sm font-semibold text-gray-700"
                                >
                                    Confirm password
                                </label>

                                <div className="flex items-center rounded-xl border border-gray-200 bg-gray-50 pr-3 transition focus-within:border-indigo-500 focus-within:ring-4 focus-within:ring-indigo-100">
                                    <input
                                        id="confirmPassword"
                                        type={showConfirmPassword ? "text" : "password"}
                                        autoComplete="new-password"
                                        placeholder="Confirm new password"
                                        value={confirmPassword}
                                        onChange={(e) => setConfirmPassword(e.target.value)}
                                        className="w-full bg-transparent px-4 py-3 outline-none"
                                        required
                                        minLength={8}
                                    />

                                    <button
                                        type="button"
                                        onClick={() =>
                                            setShowConfirmPassword(!showConfirmPassword)
                                        }
                                        aria-label={
                                            showConfirmPassword ? "Hide password" : "Show password"
                                        }
                                        className="text-gray-500 hover:text-indigo-600"
                                    >
                                        {showConfirmPassword ? (
                                            <EyeOff size={19} />
                                        ) : (
                                            <Eye size={19} />
                                        )}
                                    </button>
                                </div>
                            </div>

                            {error && (
                                <p
                                    role="alert"
                                    className="rounded-xl bg-red-50 p-3 text-sm font-medium text-red-600"
                                >
                                    {error}
                                </p>
                            )}

                            <button
                                type="submit"
                                disabled={loading}
                                className="flex w-full items-center justify-center gap-2 rounded-xl bg-indigo-600 px-4 py-3 font-bold text-white shadow-lg shadow-indigo-200 transition hover:bg-indigo-700 disabled:cursor-not-allowed disabled:opacity-60"
                            >
                                {loading && (
                                    <Loader2 size={18} className="animate-spin" />
                                )}
                                {loading ? "Resetting..." : "Reset password"}
                            </button>
                        </form>
                    </>
                )}

                <p className="mt-8 text-center text-sm text-gray-500">
                    Remember your password?{" "}
                    <Link
                        to="/login"
                        className="font-bold text-indigo-600 hover:text-indigo-700"
                    >
                        Sign in
                    </Link>
                </p>
            </div>
        </div>
    );
}